class Solution { private Map<Integer,Integer> memo=new HashMap<>();public int racecar(int target){if(memo.containsKey(target))return memo.get(target);int n=32-Integer.numberOfLeadingZeros(target);if((1<<n)-1==target)return n;int answer=n+1+racecar((1<<n)-1-target);int forward=(1<<(n-1))-1;for(int m=0;m<n-1;m++){int backward=(1<<m)-1;answer=Math.min(answer,n+m+1+racecar(target-forward+backward));}memo.put(target,answer);return answer;} }
